class Solution {
    boolean isPal = true;
    ListNode temp = null;
    public void recursive(ListNode head) {
        if(head!=null) {
            recursive(head.next);
            if(head.val != temp.val) {
                isPal = false;
            }
            temp=temp.next;
        } 
    }
    public boolean isPalindrome(ListNode head) {
        this.temp = head;
        recursive(head);
        return isPal;
    }
}
